/**
 * Scanner precision against the planted-drift fixture. Ground truth is
 * test/fixtures/drift-demo/EXPECTED.json, generated by the fixture's own script;
 * never hand-edit expected values here.
 */

import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { describe, expect, it } from "vitest"
import { scanRepo } from "../src/pipeline.js"
import type { ShortlistedCandidate } from "../src/types.js"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const FIXTURE_ROOT = path.resolve(__dirname, "fixtures/drift-demo")

type ExpectedJson = {
  targets: { detectionRecall: number; minPrecision: number; maxFalsePositives: number; lineMatchTolerance: number }
  cases: Array<{ id: string; file: string; line: number | null; expect: { detected: boolean; matchedComponent?: string | null } }>
  negatives: Array<{ id: string; file: string; line: number | null }>
}

const expected: ExpectedJson = JSON.parse(fs.readFileSync(path.join(FIXTURE_ROOT, "EXPECTED.json"), "utf8"))
const tolerance = expected.targets.lineMatchTolerance

function at(c: ShortlistedCandidate, file: string, line: number): boolean {
  const want = path.join(FIXTURE_ROOT, file).replace(/\\/g, "/")
  return c.file.replace(/\\/g, "/") === want && Math.abs(c.line - line) <= tolerance
}

describe("scanner precision against the drift-demo fixture", () => {
  const { shortlisted, dsIndex } = scanRepo({ root: FIXTURE_ROOT })

  it("indexes the fixture's design system", () => {
    expect(dsIndex.components.map((c) => c.name)).toEqual(
      expect.arrayContaining(["Button", "Card", "Alert", "Badge", "Input", "Dialog", "Table"])
    )
  })

  it("resolves import paths through the tsconfig alias", () => {
    const button = dsIndex.components.find((c) => c.name === "Button")
    expect(button?.importPath).toBe("@/components/ui/button")
  })

  it(`meets detection recall >= ${expected.targets.detectionRecall}`, () => {
    const misses = expected.cases
      .filter((c) => c.expect.detected && c.line !== null)
      .filter(
        (c) =>
          !shortlisted.some(
            (s) => at(s, c.file, c.line!) && (!c.expect.matchedComponent || s.shortlist.includes(c.expect.matchedComponent))
          )
      )
      .map((c) => `${c.id} (${c.file}:${c.line})`)
    expect(misses).toEqual([])
    const recall = (expected.cases.length - misses.length) / expected.cases.length
    expect(recall).toBeGreaterThanOrEqual(expected.targets.detectionRecall)
  })

  it(`meets precision >= ${expected.targets.minPrecision}`, () => {
    const falsePositives = shortlisted.filter(
      (s) => !expected.cases.some((c) => c.line !== null && at(s, c.file, c.line))
    )
    const precision = (shortlisted.length - falsePositives.length) / shortlisted.length
    expect(precision).toBeGreaterThanOrEqual(expected.targets.minPrecision)
    expect(falsePositives.length).toBeLessThanOrEqual(expected.targets.maxFalsePositives)
  })

  it("never flags a known negative", () => {
    const flagged = expected.negatives.filter((n) => n.line !== null && shortlisted.some((s) => at(s, n.file, n.line!)))
    expect(flagged.map((n) => n.id)).toEqual([])
  })

  it("restricts scanning to onlyFiles when given", () => {
    const only = scanRepo({ root: FIXTURE_ROOT, onlyFiles: [path.join(FIXTURE_ROOT, "app/billing/page.tsx")] })
    expect(only.shortlisted.length).toBeGreaterThan(0)
    expect(only.shortlisted.every((s) => s.file.replace(/\\/g, "/").endsWith("app/billing/page.tsx"))).toBe(true)
  })
})
